/*
 * net_io_$put_in_sock_common - Deliver a packet to a socket of this node
 *
 * Original address: 0x00E0E238 (SAU2 map: first routine of the NET_IO code
 * segment "I E0E238 NET_IO size = 68C", no symbol of its own; was
 * FUN_00e0e238)
 * Size: 610 bytes (0x00E0E238 .. 0x00E0E499); its RINGLOG header-info cell
 * and crash status follow at 0x00E0E49A and 0x00E0E49C.
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,-0x68; D2-D7/A2-A4 saved).  A5 is NOT loaded here: the
 * body runs on its callers' A5, which all of them set to 0xE244F0, the NET_IO
 * data segment (NET_IO_$PUT_IN_SOCK "lea (0xe244f0).l,A5" 0x00E0E4A6), so
 * (A5) is NET_IO_$ALL_F_ADDR and (0xA4/0xA6/0xA8,A5) are RING_$OVERFLOW_OVERFLOW,
 * RING_$FILE_OVERFLOW and RING_$DELIVERY_FAILED:
 *   (0x08,A6) port (D3)        (0x0C,A6) port_type word
 *   (0x0E,A6) socket word (D2) (0x10,A6) int_level byte (D4)
 *   (0x12,A6) hdr_va_p (A4)    (0x16,A6) data_pa_p
 *   (0x1A,A6) hdr_len (D5)     (0x1C,A6) data_len (D6)
 *   (0x1E,A6) ec_ret
 *   (-0x54) clock, (-0x48) the 0x40-byte sock_$pkt_info_t, (-0x5E) result;
 *   D3w the destination socket, D7b "routed to ROUTE_$SOCK".
 *
 * Blocks:
 *   0x00E0E258-0x00E0E26C  log the inbound header when ring logging is on
 *   0x00E0E26E-0x00E0E29E  no port given: find it (none: crash "unknown
 *                          network port")
 *   0x00E0E2A0-0x00E0E2BE  routing_type 1: advance the route index and take
 *                          the destination socket from the route word
 *   0x00E0E2C0-0x00E0E300  internet: drop an all-ones source node; fill a
 *                          zero source network from the port; to this node
 *                          (or a broadcast) take dest.sock, otherwise hand
 *                          the packet to the routing socket ROUTE_$SOCK
 *   0x00E0E302-0x00E0E324  drop a broadcast to socket 4 of dest_node 2 whose
 *                          header byte +0x07 has bit 3 set
 *   0x00E0E328-0x00E0E39C  stamp the header with the arrival time (the
 *                          full clock when server logging, else
 *                          TIME_$CLOCKH), count it on the port (+0x54),
 *                          build the socket record
 *   0x00E0E3A2-0x00E0E3E6  queue it (SOCK_$PUT_INT when int_level is true,
 *                          else SOCK_$PUT); queued: return true
 *   0x00E0E3EA-0x00E0E442  socket 2 full: count RING_$FILE_OVERFLOW and try
 *                          socket 6; queued: return true, full too: count
 *                          RING_$OVERFLOW_OVERFLOW and drop
 *   0x00E0E444-0x00E0E466  otherwise count ROUTE_$Q_OFLO (the routing
 *                          socket) or RING_$DELIVERY_FAILED
 *   0x00E0E46A-0x00E0E498  drop: return the header, dump the data pages,
 *                          return false
 *
 * Quirks reproduced:
 *   - A packet the socket refused is still stamped and counted on the port
 *     (+0x54) before it is freed.
 *   - The header's first longword (dest_node) and bytes 5-6 are overwritten
 *     with the arrival time.
 *   - The socket record's dst_addr (+0x0C), hole (+0x0A..) and hops are not
 *     written: whatever the stack held goes to the socket.
 *   - Its src_addr/src_port slots carry the clock (high long, low word).
 *   - The ROUTE_$SOCK comparison zero-extends the socket and sign-extends
 *     ROUTE_$SOCK (0x00E0E444-0x00E0E44E).
 *   - PKT_$DUMP_DATA is called with a reserved result slot that nothing
 *     reads (0x00E0E47C).
 */

#include "net_io/net_io_internal.h"
#include "misc/misc.h"
#include "netbuf/netbuf.h"
#include "netlog/netlog.h"
#include "node/node.h"
#include "pkt/pkt.h"
#include "ring/ring.h"
#include "ring/ringlog.h"

/*
 * The header-info cell handed to RINGLOG_$LOGIT (`pea (0x236,PC)` at
 * 0x00E0E262 = 0x00E0E49A, bytes ff 00): bit 7 of byte 0 set, an inbound
 * packet.
 */
static const uint8_t net_io_$put_ringlog_info[2] = { 0xFF, 0x00 };

/*
 * `pea (0x20a,PC)` at 0x00E0E290 = 0x00E0E49C, bytes 00 2b 00 03:
 * "unknown network port".
 */
static const status_$t net_io_$put_crash_status =
    status_$internet_unknown_network_port;

/* pkt_$hdr_t.routing_type of a local packet (`cmp.w D1w,D0w`, D1 = 1) */
#define NET_IO_ROUTING_LOCAL        1

/* The node bits compared (`move.l #0xffffff,D0`) */
#define NET_IO_NODE_MASK            0x00FFFFFFu

/* The drop test at 0x00E0E302-0x00E0E324 */
#define NET_IO_DROP_DEST_NODE       2
#define NET_IO_DROP_SOCKET          4
#define NET_IO_DROP_BYTE7_BIT       0x08    /* btst.l #0x3 on byte +0x07 */

/* Socket 2 and its overflow socket 6 (0x00E0E3EA, 0x00E0E40C) */
#define NET_IO_FILE_SOCKET          2
#define NET_IO_OVERFLOW_SOCKET      6

int8_t net_io_$put_in_sock_common(route_$port_t *port, uint16_t port_type,
                                  uint16_t socket, int8_t int_level,
                                  uint32_t *hdr_va_p, uint32_t *data_pa_p,
                                  uint16_t hdr_len, uint16_t data_len,
                                  ec_$eventcount_t **ec_ret)
{
    clock_t now;                        /* (-0x54,A6) */
    sock_$pkt_info_t rec;               /* (-0x48,A6) */
    int8_t result;                      /* (-0x5E,A6) */
    pkt_$hdr_t *hdr;                    /* A2 */
    uint16_t dsock;                     /* D3w */
    int8_t to_router;                   /* D7b */
    int8_t queued;                      /* D0b */
    int16_t i;

    /* 0x00E0E258-0x00E0E26C */
    if (RINGLOG_$CTL.logging_active < 0) {
        RINGLOG_$LOGIT(net_io_$put_ringlog_info, ARCH_VA_TO_PTR(*hdr_va_p));
    }

    /* 0x00E0E26E-0x00E0E29E */
    to_router = 0;
    if (port == NULL) {
        port = ROUTE_$FIND_PORTP(port_type, (int32_t)(uint32_t)socket);
        if (port == NULL) {
            CRASH_SYSTEM(&net_io_$put_crash_status);
        }
    }

    hdr = (pkt_$hdr_t *)ARCH_VA_TO_PTR(*hdr_va_p);
    if (hdr->routing_type == NET_IO_ROUTING_LOCAL) {
        /*
         * 0x00E0E2AE-0x00E0E2BA: "move.w (0x1c,A2,D0w*0x1),D3w" with D0 =
         * route_count * 2 after the increment, i.e. the route_count'th word
         * counting src_node_lo (+0x1C) as word 0.
         */
        hdr->route_count++;
        dsock = ((const uint16_t *)(const void *)
                 ((const uint8_t *)hdr + 0x1C))[hdr->route_count];
    } else {
        /* 0x00E0E2C0-0x00E0E2CE */
        if ((hdr->u.inet.src.node & NET_IO_NODE_MASK & NET_IO_$ALL_F_ADDR) ==
            NET_IO_$ALL_F_ADDR) {
            goto drop;
        }
        /* 0x00E0E2D2-0x00E0E2D8 */
        if (hdr->u.inet.src.net == 0) {
            hdr->u.inet.src.net = port->network;
        }
        /* 0x00E0E2DC-0x00E0E300 */
        if ((hdr->u.inet.dest.node & NET_IO_NODE_MASK) == NODE_$ME ||
            (int8_t)hdr->info_flags < 0) {
            dsock = hdr->u.inet.dest.sock;
        } else {
            dsock = ROUTE_$WIRED_DATA.sock;
            to_router = (int8_t)0xFF;
        }
    }

    /* 0x00E0E302-0x00E0E324 */
    if (hdr->dest_node == NET_IO_DROP_DEST_NODE &&
        dsock == NET_IO_DROP_SOCKET &&
        (int8_t)hdr->info_flags < 0 &&
        (hdr->zero_05[2] & NET_IO_DROP_BYTE7_BIT) != 0) {
        goto drop;
    }

    /* 0x00E0E328-0x00E0E35C */
    TIME_$ABS_CLOCK(&now);
    if (NETLOG_$OK_TO_LOG_SERVER < 0) {
        /* "andi.l #-0xffff01,(0x4,A2); lsl.l #8; or.l": bytes 5-6 */
        hdr->dest_node = now.high;
        hdr->zero_05[0] = (uint8_t)(now.low >> 8);
        hdr->zero_05[1] = (uint8_t)now.low;
    } else {
        hdr->dest_node = TIME_$CLOCKH;
    }
    port->stat_long_54++;

    /* 0x00E0E360-0x00E0E39C */
    result = (int8_t)0xFF;
    rec.hdr = ARCH_PTR_TO_VA(hdr);
    rec.hdr_len = hdr_len;
    rec.data_len = data_len;
    rec.n_hops = 0;
    for (i = 3; i >= 0; i--) {          /* moveq #3 / dbf: 4 longs */
        rec.data_pages[3 - i] = data_pa_p[3 - i];
    }
    rec.flags = 0;
    rec.src_addr = now.high;
    rec.src_port = now.low;

    /* 0x00E0E3A2-0x00E0E3E6 */
    if (int_level < 0) {
        queued = SOCK_$PUT_INT(dsock, &rec, (int8_t)~to_router, port_type,
                               socket, ec_ret);
    } else {
        queued = SOCK_$PUT(dsock, &rec, (int8_t)~to_router, port_type, socket);
    }
    if (queued < 0) {
        return result;
    }

    if (dsock == NET_IO_FILE_SOCKET) {
        /* 0x00E0E3F0-0x00E0E442 */
        RING_$FILE_OVERFLOW++;
        if (int_level < 0) {
            queued = SOCK_$PUT_INT(NET_IO_OVERFLOW_SOCKET, &rec,
                                   (int8_t)~to_router, port_type, socket,
                                   ec_ret);
        } else {
            queued = SOCK_$PUT(NET_IO_OVERFLOW_SOCKET, &rec,
                               (int8_t)~to_router, port_type, socket);
        }
        if (queued < 0) {
            return result;
        }
        RING_$OVERFLOW_OVERFLOW++;
    } else if ((uint32_t)dsock ==
                   (uint32_t)(int32_t)(int16_t)ROUTE_$WIRED_DATA.sock &&
               ROUTE_$WIRED_DATA.sock != 0xFFFF) {
        /* 0x00E0E444-0x00E0E464 */
        ROUTE_$RTWIRED_DATA.q_oflo++;
    } else {
        /* 0x00E0E466 */
        RING_$DELIVERY_FAILED++;
    }

drop:
    /* 0x00E0E46A-0x00E0E48C */
    NETBUF_$RTN_HDR(hdr_va_p);
    if (*data_pa_p != 0) {
        PKT_$DUMP_DATA(data_pa_p, (int16_t)data_len);
    }
    result = 0;
    return result;
}
